// Structure du programme : 12 mois, 52 semaines.
// Rythme : 6 jours de travail + jour 7 = revue hebdomadaire. 4-5 h/jour.
// Mois à 5 semaines : 3, 6, 9, 12 (4×8 + 5×4 = 52 semaines, 364 jours + jour 365 final).

// Semaine de départ de chaque mois (index 1).
export const MONTH_FIRST_WEEK = [1, 5, 9, 14, 18, 22, 27, 31, 35, 40, 44, 48];

export function monthOfWeek(week) {
  for (let m = 12; m >= 1; m--) if (week >= MONTH_FIRST_WEEK[m - 1]) return m;
  return 1;
}
export function weekOfDay(day) {
  return Math.min(52, Math.ceil(day / 7));
}

